/// A short-lived pairing invitation generated by LVM Presenter Remote 0.1.
///
/// The value is carried in a QR code or pasted manually. It is not persisted
/// after pairing and it deliberately contains no Service/API credentials.
class PresenterRemotePairingLink {
  const PresenterRemotePairingLink({
    required this.host,
    required this.port,
    required this.pairingId,
    required this.pairingSecret,
  });

  final String host;
  final int port;
  final String pairingId;
  final String pairingSecret;

  Uri get socketUri =>
      Uri(scheme: 'ws', host: host, port: port, path: '/lvm-remote/0.1');

  Uri get uri => Uri(
    scheme: 'lvm-presenter',
    host: 'remote',
    path: '/0.1',
    queryParameters: {
      'host': host,
      'port': '$port',
      'pairingId': pairingId,
      'pairingSecret': pairingSecret,
    },
  );

  static PresenterRemotePairingLink parse(String raw) {
    final uri = Uri.tryParse(raw.trim());
    if (uri == null ||
        uri.scheme != 'lvm-presenter' ||
        uri.host != 'remote' ||
        uri.path != '/0.1') {
      throw const FormatException('invalid_presenter_remote_link');
    }
    final host = uri.queryParameters['host']?.trim() ?? '';
    final port = int.tryParse(uri.queryParameters['port'] ?? '');
    final pairingId = uri.queryParameters['pairingId']?.trim() ?? '';
    final pairingSecret = uri.queryParameters['pairingSecret']?.trim() ?? '';
    if (host.isEmpty ||
        port == null ||
        port < 1 ||
        port > 65535 ||
        pairingId.isEmpty ||
        pairingSecret.isEmpty) {
      throw const FormatException('invalid_presenter_remote_link');
    }
    return PresenterRemotePairingLink(
      host: host,
      port: port,
      pairingId: pairingId,
      pairingSecret: pairingSecret,
    );
  }
}
